import sharp from 'sharp';

/**
 * Replaces the background of an image with pure white (#FFFFFF).
 *
 * Algorithm:
 * 1. Sample pixels from corners and edges to detect background color
 * 2. Calculate average background color and create tolerance threshold
 * 3. Replace all background pixels with pure white RGB(255, 255, 255)
 *
 * @param base64Image - Base64 encoded image string (with or without data URL prefix)
 * @returns Promise resolving to processed image as base64 string (without data URL prefix)
 * @throws Error if image processing fails
 */
export async function replaceBackgroundWithWhite(base64Image: string): Promise<string> {
  try {
    // Remove data URL prefix if present
    const base64Data = base64Image.replace(/^data:image\/\w+;base64,/, '');
    const imageBuffer = Buffer.from(base64Data, 'base64');

    // Load image metadata
    const image = sharp(imageBuffer);
    const metadata = await image.metadata();

    if (!metadata.width || !metadata.height) {
      throw new Error('Unable to read image dimensions');
    }

    const { width, height } = metadata;

    // Get raw pixel data
    const { data, info } = await image
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true });

    const channels = info.channels;

    // Sample edge pixels to detect background color
    const edgePixels: Array<{ r: number; g: number; b: number }> = [];

    // Sample corners (5x5 pixel regions)
    const sampleSize = 5;
    const regions = [
      { x: 0, y: 0 }, // Top-left
      { x: width - sampleSize, y: 0 }, // Top-right
      { x: 0, y: height - sampleSize }, // Bottom-left
      { x: width - sampleSize, y: height - sampleSize }, // Bottom-right
    ];

    for (const region of regions) {
      for (let dy = 0; dy < sampleSize; dy++) {
        for (let dx = 0; dx < sampleSize; dx++) {
          const x = Math.max(0, Math.min(width - 1, region.x + dx));
          const y = Math.max(0, Math.min(height - 1, region.y + dy));
          const idx = (y * width + x) * channels;

          edgePixels.push({
            r: data[idx],
            g: data[idx + 1],
            b: data[idx + 2],
          });
        }
      }
    }

    // Calculate average background color
    const avgColor = edgePixels.reduce(
      (acc, pixel) => ({
        r: acc.r + pixel.r,
        g: acc.g + pixel.g,
        b: acc.b + pixel.b,
      }),
      { r: 0, g: 0, b: 0 }
    );

    const numSamples = edgePixels.length;
    avgColor.r = Math.round(avgColor.r / numSamples);
    avgColor.g = Math.round(avgColor.g / numSamples);
    avgColor.b = Math.round(avgColor.b / numSamples);

    console.log('[Image Processing] Detected background color:', avgColor);

    // Calculate color threshold (Euclidean distance)
    // Use a threshold that's permissive enough to catch light backgrounds
    // but not so permissive it affects the model/clothing
    const colorThreshold = 40; // Adjust based on testing

    // Replace background pixels with pure white
    for (let i = 0; i < data.length; i += channels) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];

      // Calculate color distance from detected background
      const distance = Math.sqrt(
        Math.pow(r - avgColor.r, 2) +
        Math.pow(g - avgColor.g, 2) +
        Math.pow(b - avgColor.b, 2)
      );

      // If pixel is similar to background, replace with white
      if (distance <= colorThreshold) {
        data[i] = 255;     // R
        data[i + 1] = 255; // G
        data[i + 2] = 255; // B
        // Keep alpha channel unchanged (i + 3)
      }
    }

    // Create new image from modified pixel data
    const processedBuffer = await sharp(data, {
      raw: {
        width,
        height,
        channels,
      },
    })
      .png()
      .toBuffer();

    // Convert to base64
    const processedBase64 = processedBuffer.toString('base64');

    console.log('[Image Processing] Background replacement completed');

    return processedBase64;
  } catch (error) {
    console.error('[Image Processing] Error replacing background:', error);
    throw new Error(`Failed to process image: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

